//! `tetel target <symbol> --cites F#` — declare a symbol this design
//! tells an implementer to modify, and point at the census that
//! establishes where it is used.
//!
//! # Why the trigger is a declaration
//!
//! The rule this implements was first written as "refuse a memo whose
//! recommendation names an uncensused symbol". That has no decidable
//! trigger. Nothing in [`crate::claims`] or [`crate::prose`] types a
//! record as a recommendation — a claim is a proposition with fact
//! citations, a prose block is text with claim citations — so "the
//! memo's recommendations" denotes no set a check can enumerate, and
//! deciding from English that a sentence tells an implementer to modify
//! something is precisely the heuristic read the project rules out as a
//! refusal trigger.
//!
//! The obvious repair — trigger on any symbol a claim's proposition
//! mentions — is not merely off-charter, it is already measured dead in
//! this crate. [`crate::scope`] tried string-matching symbol references
//! and rejected the detector: it flagged a legitimate quotation and
//! missed both real overreaches. Naming a symbol the code you read calls
//! is normal; concluding about it is the failure; string matching cannot
//! tell them apart, and a refusal wired to it would make honest memos
//! unwritable.
//!
//! So the trigger is a declaration, and the refusal never reads English
//! at all.
//!
//! # Where the refusal lives, and why here
//!
//! At declaration — the earliest surface that can decide it. `target`
//! refuses a symbol whose cited fact carries no qualifying census entry,
//! the same authoring-time shape as [`crate::facts`] refusing an empty
//! pending buffer.
//!
//! A fact's extent is immutable once minted and a target is immutable
//! once declared, so this one refusal makes *every declared target is
//! censused* a workspace invariant. `render` therefore needs no refusal
//! of its own: its job is to emit the section. What `render` cannot
//! vouch for — a hand-authored or tampered document that never passed
//! through this verb — [`crate::checks`] re-verifies against the
//! shipped snapshot.
//!
//! This is the report-versus-refuse discriminator from the other side
//! than [`crate::scope`] landed on. That check stayed human-owed because
//! only a person can tell context from conclusion. Here nothing is left
//! to tell: the remedy is singular. Run the workspace-rooted grep, mint
//! the fact, cite it — or withdraw the target.
//!
//! # What declaration cannot reach
//!
//! Under-declaration. Deciding that a memo recommended something it
//! never declared is the same heuristic read the trigger just rejected,
//! so no refusal can reach it and none is attempted. The answer is
//! visibility instead: the rendered section does not disappear when it
//! is empty, so a memo full of tell-the-implementer language with an
//! empty census section shows its hole to every reader — and `check`'s
//! standing non-coverage list says the blind spot is there.
//!
//! # Withdrawable, not revisable
//!
//! A changed symbol is a different census, so the honest edit is
//! withdraw and redeclare rather than revise. There is deliberately no
//! `Revise` variant: a revision that could change the symbol while
//! keeping the citation would break the invariant this module exists to
//! establish.

use std::io;
use std::path::{Path, PathBuf};

use serde::{Deserialize, Serialize};

use crate::facts;
use crate::workspace::{self, AuthoringError, Kind};

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "event")]
pub enum TargetEvent {
    Declare {
        id: String,
        symbol: String,
        /// The fact whose extent censuses `symbol`. One fact, not a
        /// list: the predicate is about a single search, and a target
        /// resting on "one of these several facts" would leave which one
        /// undecided.
        from: String,
        timestamp: u64,
    },
    Withdraw {
        id: String,
        why: String,
        timestamp: u64,
    },
}

#[derive(Debug, Clone)]
pub struct Target {
    pub id: String,
    pub symbol: String,
    pub from: String,
    pub withdrawn: bool,
}

fn log_path(workspace_dir: &Path) -> PathBuf {
    workspace_dir.join("targets.jsonl")
}

pub fn load_all(workspace_dir: &Path) -> io::Result<Vec<Target>> {
    let events: Vec<TargetEvent> = workspace::read_jsonl(&log_path(workspace_dir))?;
    let mut by_id: std::collections::BTreeMap<String, Target> = std::collections::BTreeMap::new();
    let mut order: Vec<String> = Vec::new();
    for ev in events {
        match ev {
            TargetEvent::Declare { id, symbol, from, .. } => {
                order.push(id.clone());
                by_id.insert(id.clone(), Target { id, symbol, from, withdrawn: false });
            }
            TargetEvent::Withdraw { id, .. } => {
                if let Some(t) = by_id.get_mut(&id) {
                    t.withdrawn = true;
                }
            }
        }
    }
    Ok(order.into_iter().filter_map(|id| by_id.remove(&id)).collect())
}

/// `tetel target <symbol> --cites F1`.
///
/// Refuses unless the cited fact's captured extent contains a
/// whole-search record whose pattern byte-equals `symbol` and which was
/// rooted at the worktree it was taken against — see
/// [`facts::ExtentEntry::censuses`].
pub fn declare(workspace_dir: &Path, symbol: &str, from: &str) -> Result<Target, AuthoringError> {
    let symbol = symbol.trim();
    if symbol.is_empty() {
        return Err(workspace::refuse(workspace_dir, "target", "no symbol given; a modification target names one symbol"));
    }
    let from = from.trim();
    if from.is_empty() {
        return Err(workspace::refuse(
            workspace_dir,
            "target",
            format!(
                "a modification target must cite the fact that censuses it (--cites was missing); capture one with `tetel look --grep {symbol} <worktree root>` then `tetel fact`"
            ),
        ));
    }

    let all = facts::load_all(workspace_dir)?;
    let Some(fact) = all.iter().find(|f| f.id == from) else {
        return Err(workspace::refuse(
            workspace_dir,
            "target",
            format!("cited fact does not exist: {from}; try `tetel query facts` to see what exists"),
        ));
    };

    if !fact.extent.iter().any(|e| e.censuses(symbol)) {
        // Say which of the three ways it failed, because the remedies
        // differ and a bare refusal would send the author guessing.
        let why = diagnose(fact, symbol);
        return Err(workspace::refuse(
            workspace_dir,
            "target",
            format!(
                "{from} does not census `{symbol}`: {why}\n\
                 a census is one search of the whole worktree for the symbol itself:\n\
                 \x20   tetel look --grep {symbol} <worktree root>\n\
                 \x20   tetel fact --note \"...\"\n\
                 then cite that fact. The refusal is about the search's existence and where it was rooted, never about what it found."
            ),
        ));
    }

    let id = workspace::next_id(workspace_dir, Kind::Target)?;
    let event = TargetEvent::Declare {
        id: id.clone(),
        symbol: symbol.to_string(),
        from: from.to_string(),
        timestamp: workspace::now_unix(),
    };
    workspace::append_jsonl(&log_path(workspace_dir), &event)?;
    Ok(Target { id, symbol: symbol.to_string(), from: from.to_string(), withdrawn: false })
}

/// Which half of the predicate the cited fact failed, in the author's
/// terms. Never a score and never a guess — each branch reports a
/// property that was read off the record.
fn diagnose(fact: &facts::Fact, symbol: &str) -> String {
    use crate::pending::ObservationKind::{NoMatch, Search};
    let searches: Vec<&facts::ExtentEntry> =
        fact.extent.iter().filter(|e| matches!(e.kind, Some(Search) | Some(NoMatch))).collect();

    if searches.is_empty() {
        if fact.extent.iter().any(|e| e.kind.is_none()) {
            return "its extent was minted before searches recorded where they were rooted, so it cannot be read as a census — re-run the grep".to_string();
        }
        return "its extent contains no search at all — it was read or run, not grepped".to_string();
    }
    let patterns: Vec<&str> = searches.iter().map(|e| e.pattern.as_str()).filter(|p| !p.is_empty()).collect();
    if !patterns.iter().any(|p| *p == symbol) {
        return format!(
            "it searched for {} — a census must search for the symbol itself, byte for byte",
            patterns.iter().map(|p| format!("`{p}`")).collect::<Vec<_>>().join(", ")
        );
    }
    for e in &searches {
        if e.pattern == symbol {
            if e.world_root.is_empty() || e.world_root == crate::worldstate::NO_GIT {
                return "its search was not taken against a git worktree, so `rooted at the worktree` has no answer".to_string();
            }
            return format!(
                "its search was rooted at {}, not at the worktree root {} — so it cannot support a statement about every use of the symbol",
                e.key, e.world_root
            );
        }
    }
    unreachable!("a matching pattern was found above")
}

/// `tetel target --withdraw <id> --why <text>`.
pub fn withdraw(workspace_dir: &Path, id: &str, why: &str) -> Result<Target, AuthoringError> {
    if why.trim().is_empty() {
        return Err(workspace::refuse(workspace_dir, "target", "--withdraw requires --why"));
    }
    let all = load_all(workspace_dir)?;
    let Some(t) = all.iter().find(|t| t.id == id) else {
        return Err(workspace::refuse(workspace_dir, "target", format!("no target `{id}` in this workspace")));
    };
    if t.withdrawn {
        return Err(workspace::refuse(workspace_dir, "target", format!("{id} is already withdrawn")));
    }
    let event = TargetEvent::Withdraw { id: id.to_string(), why: why.to_string(), timestamp: workspace::now_unix() };
    workspace::append_jsonl(&log_path(workspace_dir), &event)?;
    Ok(Target { id: t.id.clone(), symbol: t.symbol.clone(), from: t.from.clone(), withdrawn: true })
}

/// What `tetel target` was asked to do. The single shape both the CLI
/// and the MCP server build and pass to [`dispatch`], so the two front
/// ends cannot drift on which act they performed — this render path has
/// already recorded one CLI/MCP drift on a duplicated act.
pub enum TargetRequest {
    Declare { symbol: Option<String>, from: Option<String> },
    Withdraw { id: String, why: Option<String> },
}

pub enum TargetOutcome {
    Declared(Target),
    Withdrawn { id: String },
}

pub fn dispatch(workspace_dir: &Path, req: TargetRequest) -> Result<TargetOutcome, AuthoringError> {
    match req {
        TargetRequest::Declare { symbol, from } => {
            let symbol = symbol.unwrap_or_default();
            let from = from.unwrap_or_default();
            declare(workspace_dir, &symbol, &from).map(TargetOutcome::Declared)
        }
        TargetRequest::Withdraw { id, why } => {
            let why = why.unwrap_or_default();
            withdraw(workspace_dir, &id, &why).map(|t| TargetOutcome::Withdrawn { id: t.id })
        }
    }
}

//! `tetel fact` — mints a fact from the pending observation buffer (see
//! `pending.rs`). Refuses on an empty buffer. There is deliberately no
//! flag anywhere on this module's CLI surface that lets a caller supply
//! the extent or captured output themselves — that absence is the
//! guarantee that a fact was actually backed by a `look`/`run`, not a
//! rule enforced after the fact.
//!
//! `tetel fact --revise <id> --why <text>` rewrites the note only,
//! append-only: extent, output and pin are set once at mint time and
//! never appear in a revision event at all, so there is no code path
//! that could change them later either.

use std::io;
use std::path::{Path, PathBuf};

use serde::{Deserialize, Serialize};

use crate::evidence::sha256_hex;
use crate::pending;
use crate::workspace::{self, AuthoringError, Kind};

/// One observation folded into a fact's extent — the label a human
/// reads, the key overlap detection compares, and the world-tree marker
/// it was captured under (fix 1 in the design memo).
///
/// The marker is two fields, not one. `world_state` alone cannot be
/// compared across observations of different repositories, and half the
/// workspaces in the store on 2026-08-07 read more than one; only
/// "same `world_root`, different `world_state`" is a finding. See
/// `worldstate.rs`.
///
/// `world_root` is `#[serde(default)]` for entries minted before it
/// existed. An empty root is not "unknown repository" — it marks a state
/// that was resolved from the process's working directory rather than
/// from what the observation touched, and is therefore comparable with
/// nothing. `check` treats it that way rather than guessing.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ExtentEntry {
    pub key: String,
    pub label: String,
    #[serde(default)]
    pub world_root: String,
    pub world_state: String,
    /// What kind of observation this entry came from, or `None` for one
    /// minted before the field existed.
    ///
    /// An observation's kind did not use to survive the fold — the extent
    /// kept key, label and marker, and what produced them was recoverable
    /// only by reading the label as prose. TET-28's census predicate has
    /// to distinguish a whole-search record from a per-file hit, so the
    /// kind is carried structurally.
    ///
    /// `None` means *not recorded*, never *some default kind*: a fact
    /// minted by an older build can therefore never satisfy a census
    /// requirement, and the remedy is the cheap one — run the grep again.
    #[serde(default)]
    pub kind: Option<crate::pending::ObservationKind>,
    /// The search pattern on a whole-search record, empty otherwise and
    /// on entries minted before the field existed. See
    /// [`crate::pending::PendingEntry::pattern`].
    #[serde(default)]
    pub pattern: String,
}

impl ExtentEntry {
    /// Whether this entry is a whole-search record rooted at the tree it
    /// was taken against — TET-28's census predicate, in one place.
    ///
    /// Both halves of the comparison are tool-captured: the key by
    /// `observe::search_key`, the root by `worldstate`. No authoring
    /// surface accepts an extent, so neither side can be typed.
    ///
    /// The `Search`/`NoMatch` pair is deliberate. A search that found
    /// nothing is as complete a census as one that found everything —
    /// the predicate is about existence and rooting, never about what was
    /// found, so a symbol with no occurrences is censused by the grep
    /// that established it has none.
    pub fn censuses(&self, symbol: &str) -> bool {
        use crate::pending::ObservationKind::{NoMatch, Search};
        matches!(self.kind, Some(Search) | Some(NoMatch))
            && self.pattern == symbol
            && !self.world_root.is_empty()
            && self.world_root != crate::worldstate::NO_GIT
            && self.key == self.world_root
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "event")]
pub enum FactEvent {
    Create {
        id: String,
        note: String,
        extent: Vec<ExtentEntry>,
        output: String,
        pin: String,
        timestamp: u64,
    },
    /// Append-only note revision. No `extent`, `output` or `pin` field
    /// exists on this variant at all — see the module doc comment.
    Revise {
        id: String,
        note: String,
        why: String,
        timestamp: u64,
    },
}

/// A fact's current view, replayed from its event log: the original
/// extent/output/pin (never revisable) plus whichever note is current.
pub struct Fact {
    pub id: String,
    pub note: String,
    pub extent: Vec<ExtentEntry>,
    pub output: String,
    pub pin: String,
    pub revisions: usize,
}

fn log_path(workspace_dir: &Path) -> PathBuf {
    workspace_dir.join("facts.jsonl")
}

pub fn load_all(workspace_dir: &Path) -> io::Result<Vec<Fact>> {
    let events: Vec<FactEvent> = workspace::read_jsonl(&log_path(workspace_dir))?;
    let mut by_id: std::collections::BTreeMap<String, Fact> = std::collections::BTreeMap::new();
    let mut order: Vec<String> = Vec::new();
    for ev in events {
        match ev {
            FactEvent::Create { id, note, extent, output, pin, .. } => {
                order.push(id.clone());
                by_id.insert(id.clone(), Fact { id, note, extent, output, pin, revisions: 0 });
            }
            FactEvent::Revise { id, note, .. } => {
                if let Some(f) = by_id.get_mut(&id) {
                    f.note = note;
                    f.revisions += 1;
                }
            }
        }
    }
    Ok(order.into_iter().filter_map(|id| by_id.remove(&id)).collect())
}

pub fn exists(workspace_dir: &Path, id: &str) -> io::Result<bool> {
    Ok(load_all(workspace_dir)?.iter().any(|f| f.id == id))
}

pub fn get(workspace_dir: &Path, id: &str) -> io::Result<Option<Fact>> {
    Ok(load_all(workspace_dir)?.into_iter().find(|f| f.id == id))
}

/// How old each observation in the buffer is, at the moment it is folded.
///
/// `fact` prints this because a buffer is not necessarily what you just
/// looked at. A revision does not clear it and a failed `look` does not
/// add to it, so a mint can fold an observation from an earlier line of
/// enquiry — which happened, silently, producing a fact whose note
/// described two source files its extent never covered.
///
/// Reported rather than refused, and without a staleness threshold: there
/// is no age at which folding an earlier observation becomes wrong, and a
/// number chosen here would be arbitrary. What was missing was not a rule
/// but the fact being visible at all — an author who expected two file
/// reads and is told they folded one four-minute-old command has what
/// they need.
pub fn describe_buffer(entries: &[crate::pending::PendingEntry], now: u64) -> Vec<String> {
    entries
        .iter()
        .map(|e| {
            let age = now.saturating_sub(e.captured_at);
            let when = if e.captured_at == 0 {
                "age unknown".to_string()
            } else if age < 60 {
                format!("{age}s ago")
            } else {
                format!("{}m ago", age / 60)
            };
            format!("{} ({when})", e.label)
        })
        .collect()
}

/// When this workspace last minted a fact, or `None` if it never has.
///
/// Reads the raw event log rather than [`load_all`], which discards
/// `Create`'s timestamp when building its in-memory view. The timestamp
/// is in the shipped file the whole time; only the view drops it.
pub fn last_mint_timestamp(workspace_dir: &Path) -> Option<u64> {
    let events: Vec<FactEvent> = workspace::read_jsonl(&log_path(workspace_dir)).ok()?;
    events
        .iter()
        .filter_map(|e| match e {
            FactEvent::Create { timestamp, .. } => Some(*timestamp),
            FactEvent::Revise { .. } => None,
        })
        .max()
}

/// Every refusal this workspace recorded since its last mint, verbatim.
///
/// # Why a mint reports what it could not do
///
/// [`describe_buffer`] says what a mint *folded*. It cannot say why what
/// the author expected to fold is missing — and that gap is the whole
/// incident this exists for: two `look` calls were refused for a
/// malformed line range, each left the pending buffer untouched, and the
/// next mint folded a leftover observation from an earlier line of
/// enquiry. The author saw a folding line with an age on it and nothing
/// else. The refusals had happened, and nothing the tool ever consults
/// had recorded them.
///
/// So the two halves are complementary and both are needed: what was
/// folded, and what was refused in the window that produced it. Neither
/// is a refusal itself, neither is counted, and neither carries a
/// threshold — a mint following a refusal is often entirely correct.
///
/// One helper, called by both surfaces, so CLI and MCP cannot drift on
/// which refusals a mint reports.
pub fn refusals_since_last_mint(workspace_dir: &Path) -> Vec<String> {
    workspace::refusals_since(workspace_dir, last_mint_timestamp(workspace_dir))
}

/// One fact's mint window: the refusals recorded between the previous
/// mint and this one.
pub struct MintWindow {
    pub fact_id: String,
    pub refusals: Vec<String>,
    /// The first fact in the workspace, whose window has no previous mint
    /// to open at and so runs from the beginning of the log.
    pub is_first: bool,
    /// At least one of these refusals shares a second with a mint
    /// boundary, so it cannot be placed on one side of it. Such a refusal
    /// appears in both adjacent windows — the same `>=` choice the
    /// mint-time replay makes, for the same reason: showing twice is
    /// recoverable, hiding once is the incident this exists for.
    pub straddles_a_boundary: bool,
}

/// Every fact whose mint window contains a refusal, in mint order.
///
/// # Why this exists beside the mint-time line
///
/// [`refusals_since_last_mint`] prints at the moment of minting, and that
/// is the only moment the defect is *preventable* rather than merely
/// discoverable — a fact's extent is unrevisable, so nothing later can
/// correct the evidence, only the note.
///
/// But a line printed at a terminal works only if it is read in the
/// moment, and a memo built on a bad fact otherwise renders and checks
/// clean. This recovers the same signal at grading time, when nobody is
/// relying on the author's attention: `FactEvent::Create` carries a
/// timestamp that ships in `facts.jsonl`, and the snapshot copies
/// `refusals.log` beside it, so the windows are derivable from files
/// every snapshot already contains. No schema change, nothing new stored.
///
/// Human-owed and verbatim: a mint following a refusal is frequently
/// correct, and which of them matters is a reader's call. Nothing here
/// counts, scores or ranks.
///
/// The listing is only ever as complete as the log beneath it — a
/// snapshot written by a build that did not record surface-layer
/// refusals simply has fewer lines, and this is silent about them. That
/// is not a completeness claim in either direction: a verbatim listing
/// asserts only what was recorded.
pub fn mint_windows(snapshot_dir: &Path) -> Vec<MintWindow> {
    let Ok(events) = workspace::read_jsonl::<FactEvent>(&log_path(snapshot_dir)) else {
        return Vec::new();
    };
    let mints: Vec<(String, u64)> = events
        .iter()
        .filter_map(|e| match e {
            FactEvent::Create { id, timestamp, .. } => Some((id.clone(), *timestamp)),
            FactEvent::Revise { .. } => None,
        })
        .collect();

    let mut out = Vec::new();
    for (i, (id, minted_at)) in mints.iter().enumerate() {
        // The window opens at the previous mint — or at the beginning of
        // the log for the first fact, which owns everything refused
        // before it.
        let opened = if i == 0 { None } else { Some(mints[i - 1].1) };
        let stamped: Vec<(u64, String)> = workspace::refusals_since(snapshot_dir, opened)
            .into_iter()
            .filter_map(|line| {
                let ts = line.split_once('\t').and_then(|(ts, _)| ts.parse::<u64>().ok())?;
                (ts <= *minted_at).then_some((ts, line))
            })
            .collect();
        if !stamped.is_empty() {
            let straddles_a_boundary = stamped
                .iter()
                .any(|(ts, _)| *ts == *minted_at || opened.is_some_and(|o| *ts == o));
            out.push(MintWindow {
                fact_id: id.clone(),
                refusals: stamped.into_iter().map(|(_, line)| line).collect(),
                is_first: i == 0,
                straddles_a_boundary,
            });
        }
    }
    out
}

/// Mint a fact from the current pending buffer. Refuses if the buffer
/// is empty (a fact needs a preceding `look`/`run`) or the note text is
/// empty. Clears the buffer on success, exactly once, after the log
/// append succeeds — never before.
pub fn mint(workspace_dir: &Path, note: &str) -> Result<Fact, AuthoringError> {
    if note.trim().is_empty() {
        return Err(workspace::refuse(workspace_dir, "fact", "note text is empty"));
    }
    let buf = pending::load(workspace_dir)?;
    if buf.is_empty() {
        return Err(workspace::refuse(
            workspace_dir,
            "fact",
            "pending observation buffer is empty; run `tetel look` or `tetel run` first, then `tetel fact`",
        ));
    }

    let extent: Vec<ExtentEntry> = buf
        .iter()
        .map(|e| ExtentEntry {
            key: e.key.clone(),
            label: e.label.clone(),
            world_root: e.world_root.clone(),
            world_state: e.world_state.clone(),
            kind: Some(e.kind),
            pattern: e.pattern.clone(),
        })
        .collect();
    let output = buf.iter().filter(|e| !e.output.is_empty()).map(|e| e.output.as_str()).collect::<Vec<_>>().join("\n");

    // The pin: a content fingerprint over every entry's label, output
    // and world-tree marker — the prototype's compute_pin hashed
    // extent labels and captured output; folding the marker in too means
    // a fact minted against a different tree state pins differently even
    // if its labels/output happen to coincide. Both halves of the marker
    // go in: two observations of the same path under the same state but
    // in two different checkouts are two different observations. The
    // marker itself is still carried separately in `extent` (see
    // `ExtentEntry`), since a hash alone can't be compared by a human
    // without recomputing it — fix 1 is about visibility, not just
    // detectability.
    let mut hash_input = String::new();
    for e in &buf {
        hash_input.push_str(&e.label);
        hash_input.push('\n');
        hash_input.push_str(&e.world_root);
        hash_input.push('\n');
        hash_input.push_str(&e.world_state);
        hash_input.push('\n');
        hash_input.push_str(&e.output);
        hash_input.push('\n');
    }
    let pin = format!("sha256:{}", sha256_hex(&hash_input));

    let id = workspace::next_id(workspace_dir, Kind::Fact)?;
    let event = FactEvent::Create {
        id: id.clone(),
        note: note.to_string(),
        extent: extent.clone(),
        output: output.clone(),
        pin: pin.clone(),
        timestamp: workspace::now_unix(),
    };
    workspace::append_jsonl(&log_path(workspace_dir), &event)?;
    pending::clear(workspace_dir)?;

    Ok(Fact { id, note: note.to_string(), extent, output, pin, revisions: 0 })
}

/// `tetel fact --revise <id> --note <new-text> --why <text>`.
pub fn revise(workspace_dir: &Path, id: &str, new_note: &str, why: &str) -> Result<(), AuthoringError> {
    if !exists(workspace_dir, id)? {
        return Err(workspace::refuse(workspace_dir, "fact", format!("no such fact: {id}")));
    }
    if why.trim().is_empty() {
        return Err(workspace::refuse(workspace_dir, "fact", "--revise requires --why (revisions must explain themselves)"));
    }
    if new_note.trim().is_empty() {
        return Err(workspace::refuse(workspace_dir, "fact", "no new --note text given"));
    }
    let event =
        FactEvent::Revise { id: id.to_string(), note: new_note.to_string(), why: why.to_string(), timestamp: workspace::now_unix() };
    workspace::append_jsonl(&log_path(workspace_dir), &event)?;
    Ok(())
}

/// What `tetel fact` was asked to do — mint a new fact from the pending
/// buffer, or revise an existing one's note. The single shape both the
/// CLI and the MCP server build and pass to [`dispatch`], so the two
/// front ends can never drift on which combination of missing flags gets
/// refused, or with what text.
pub enum FactRequest {
    Mint { note: Option<String> },
    Revise { id: String, note: Option<String>, why: Option<String> },
}

pub enum FactOutcome {
    Minted(Fact),
    Revised { id: String },
}

/// Dispatches a [`FactRequest`] to [`mint`] or [`revise`], refusing with
/// the exact text the CLI has always printed for a flag a mode required
/// but didn't get — lifted here (rather than left as a bare `eprintln!`
/// in `main.rs`) so the MCP server's structured refusals carry the same
/// guidance the CLI does, from the one place that decides it.
pub fn dispatch(workspace_dir: &Path, req: FactRequest) -> Result<FactOutcome, AuthoringError> {
    match req {
        FactRequest::Mint { note } => {
            let note = note.ok_or_else(|| workspace::refuse(workspace_dir, "fact", "fact requires --note"))?;
            mint(workspace_dir, &note).map(FactOutcome::Minted)
        }
        FactRequest::Revise { id, note, why } => {
            let why = why.ok_or_else(|| workspace::refuse(workspace_dir, "fact", "fact --revise requires --why"))?;
            let note = note.ok_or_else(|| {
                workspace::refuse(workspace_dir, "fact", "fact --revise requires --note (the new note text)")
            })?;
            revise(workspace_dir, &id, &note, &why).map(|()| FactOutcome::Revised { id })
        }
    }
}

#[cfg(test)]
mod window_tests {
    use super::*;

    fn scratch(tag: &str) -> PathBuf {
        let dir = std::env::temp_dir().join(format!(
            "tetel-window-{tag}-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        ));
        std::fs::create_dir_all(&dir).unwrap();
        dir
    }

    /// Facts as raw `Create` events at chosen timestamps, plus a refusal
    /// log at chosen timestamps — the two files a snapshot ships. Written
    /// by hand because the whole point is controlling the seconds, which
    /// an end-to-end run cannot do.
    fn seed(dir: &Path, mints: &[(&str, u64)], refusals: &[(u64, &str)]) {
        let facts: String = mints
            .iter()
            .map(|(id, ts)| {
                format!(
                    r#"{{"event":"Create","id":"{id}","note":"n","extent":[],"output":"","pin":"p","timestamp":{ts}}}"#
                ) + "\n"
            })
            .collect();
        std::fs::write(dir.join("facts.jsonl"), facts).unwrap();
        let log: String =
            refusals.iter().map(|(ts, r)| format!("{ts}\tlook\t{r}\n")).collect();
        std::fs::write(dir.join("refusals.log"), log).unwrap();
    }

    #[test]
    fn each_refusal_lands_in_the_window_of_the_mint_that_followed_it() {
        let dir = scratch("attribution");
        seed(&dir, &[("F1", 100), ("F2", 200)], &[(50, "before F1"), (150, "between F1 and F2")]);

        let w = mint_windows(&dir);
        assert_eq!(w.len(), 2, "both facts have a refusal in their window");
        assert_eq!(w[0].fact_id, "F1");
        assert!(w[0].is_first, "F1 has no previous mint to open at");
        assert!(w[0].refusals[0].contains("before F1"));
        assert_eq!(w[0].refusals.len(), 1, "F1 must not claim a refusal that followed it");
        assert_eq!(w[1].fact_id, "F2");
        assert!(!w[1].is_first);
        assert!(w[1].refusals[0].contains("between F1 and F2"));
        assert_eq!(w[1].refusals.len(), 1);
        assert!(!w[0].straddles_a_boundary && !w[1].straddles_a_boundary, "no shared seconds here");

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// A refusal sharing a second with a mint cannot be placed on one
    /// side of it. It is listed under both adjacent facts and the report
    /// says why, rather than a guess being made silently — the same
    /// choice the mint-time replay makes.
    #[test]
    fn a_refusal_sharing_a_second_with_a_mint_is_flagged_not_guessed() {
        let dir = scratch("straddle");
        seed(&dir, &[("F1", 100), ("F2", 200)], &[(100, "same second as F1")]);

        let w = mint_windows(&dir);
        assert_eq!(w.len(), 2, "listed under both, since which side it fell on is unknowable");
        assert!(w[0].straddles_a_boundary, "F1's window closes at this second");
        assert!(w[1].straddles_a_boundary, "F2's window opens at it");

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// A fact with nothing refused in its window is not listed at all. An
    /// entry per fact saying "none" is noise, and noise is what makes a
    /// real one invisible.
    #[test]
    fn a_fact_with_a_clean_window_is_absent_rather_than_reported_empty() {
        let dir = scratch("clean");
        seed(&dir, &[("F1", 100), ("F2", 200)], &[(150, "only in F2's window")]);
        let w = mint_windows(&dir);
        assert_eq!(w.len(), 1);
        assert_eq!(w[0].fact_id, "F2");
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// A snapshot from a build that never recorded surface-layer
    /// refusals has no log; the listing is silent rather than absent-
    /// meaning-clean. A verbatim listing asserts only what was recorded.
    #[test]
    fn a_snapshot_with_no_refusal_log_yields_no_windows() {
        let dir = scratch("nolog");
        seed(&dir, &[("F1", 100)], &[]);
        std::fs::remove_file(dir.join("refusals.log")).unwrap();
        assert!(mint_windows(&dir).is_empty());
        let _ = std::fs::remove_dir_all(&dir);
    }
}

//! `tetel look` and `tetel run` — the only two ways an authoring workspace
//! adds to its pending observation buffer (see `pending.rs`). Mirrors
//! the prototype's `tlook`/`trun`, with two changes: `--lines A:B` is
//! new (see the module's `look_path` doc comment), and every recorded
//! observation carries a working-tree marker alongside its content
//! (fix 1 in the design memo — see `worldstate.rs`).
//!
//! Each observation resolves its **own** marker, from what it touched: a
//! `look` from the file it opened, a `--grep` match from the file it
//! matched in, a bounded negative from the search root, and a `run` from
//! this process's working directory, which is where the command actually
//! ran. Resolving one marker per call and attaching it to everything was
//! the original shape and it described the wrong tree — see the measured
//! table in `worldstate.rs`.

use std::fs;
use std::io::Read;
use std::path::Path;
use std::process::{Command, Stdio};
use std::sync::{Arc, Mutex};
use std::thread;

use crate::pending::{self, ObservationKind, PendingEntry};
use crate::workspace::{self, AuthoringError};
use crate::worldstate;

/// Resolve `path` to the key used for overlap matching: its canonical
/// absolute form when that succeeds, the path as given otherwise.
/// Canonicalization can fail on some platforms/filesystems even for a
/// path that exists (e.g. a permissions issue on an ancestor
/// directory); falling back keeps this infallible rather than losing
/// the observation over it.
fn resolve_key(path: &Path) -> String {
    fs::canonicalize(path).map(|p| p.display().to_string()).unwrap_or_else(|_| path.display().to_string())
}

/// The key for a whole-search record: the resolved search root, spelled
/// the way its own world marker spells the tree root **when the two name
/// the same directory**.
///
/// TET-28's census predicate asks whether a search was rooted at the
/// worktree, and answers it by comparing this key against the entry's own
/// `world_root`. Both are captured, but by two different tools —
/// `fs::canonicalize` here, `git rev-parse --show-toplevel` there — and
/// nothing guarantees two tools spell one directory identically. Rather
/// than have the predicate reason about that, the divergence is resolved
/// once, here, where both spellings are in hand.
///
/// The comparison is on canonicalized forms, so it is about *which
/// directory*, never about how either tool wrote it down. When they name
/// different directories — a search rooted at a subdirectory, which is
/// exactly the case the census exists to catch — the resolved root is
/// kept verbatim and the predicate's byte comparison fails, correctly.
fn search_key(root: &Path, world_root: &str) -> String {
    let resolved = resolve_key(root);
    if world_root.is_empty() {
        return resolved;
    }
    let same = fs::canonicalize(root)
        .ok()
        .zip(fs::canonicalize(world_root).ok())
        .map(|(a, b)| a == b)
        .unwrap_or(false);
    if same { world_root.to_string() } else { resolved }
}

pub struct LookOutcome {
    pub printed: String,
}

/// `tetel look <path> [--lines A:B]`.
///
/// `--lines A:B` (1-based, inclusive) is new in this port — the
/// prototype had no way to bound a read to a range, which forced
/// `tetel run sed -n '<range>p' <path>` as a workaround. That workaround
/// is exactly what produced fix 2's overlap blind spot (a `proc:`
/// observation keyed on the whole `sed` command line never overlapped
/// another range of the same file); giving `look` a first-class
/// `--lines` removes the reason to reach for `run` here at all, and its
/// key is the resolved path regardless of the range requested, so two
/// different ranges of one file always overlap each other.
///
/// A range entirely past the end of the file is not an error — it is
/// recorded as an explicit empty-range observation, the same "a bounded
/// negative must leave a trace" discipline as a zero-match grep.
pub fn look_path(workspace_dir: &Path, path: &str, lines: Option<(usize, usize)>) -> Result<LookOutcome, AuthoringError> {
    let p = Path::new(path);
    if !p.exists() {
        return Err(workspace::refuse(workspace_dir, "look", format!("no such path: {path}")));
    }
    if p.is_dir() {
        return Err(workspace::refuse(
            workspace_dir,
            "look",
            format!(
                "{path} is a directory; `tetel look` opens files. Use `tetel look --grep <pattern> {path}` to search it."
            ),
        ));
    }
    let contents = fs::read_to_string(p).map_err(|e| AuthoringError::Io(e.to_string()))?;
    let key = resolve_key(p);
    // Resolved from the file being read, never from this process's working
    // directory — see `worldstate.rs` for the measurement that forced this.
    let world = worldstate::Session::new().for_path(p);

    let (shown, label) = match lines {
        None => (contents.clone(), path.to_string()),
        Some((a, b)) => {
            if a < 1 || a > b {
                return Err(workspace::refuse(workspace_dir, "look", format!("invalid --lines range {a}:{b}")));
            }
            let all: Vec<&str> = contents.lines().collect();
            let total = all.len();
            if a > total {
                (String::new(), format!("{path} lines {a}-{b} (file has {total} line(s); nothing in range)"))
            } else {
                let end = b.min(total);
                (all[a - 1..end].join("\n"), format!("{path} lines {a}-{end}"))
            }
        }
    };

    let mut printed = String::new();
    printed.push_str(&format!("==> {path} <==\n"));
    printed.push_str(&shown);
    if !shown.is_empty() && !shown.ends_with('\n') {
        printed.push('\n');
    }

    let entry = PendingEntry {
        kind: ObservationKind::Path,
        key,
        label,
        output: shown,
        world_root: world.root,
        world_state: world.state,
        captured_at: workspace::now_unix(),
        pattern: String::new(),
    };
    let mut buf = pending::load(workspace_dir)?;
    buf.push(entry);
    pending::save(workspace_dir, &buf)?;

    Ok(LookOutcome { printed })
}

/// `tetel look --grep <pattern> <path-or-dir>`.
///
/// Shells out to the system `grep` (present on every platform this
/// crate targets), the same way `run_command` shells out to whatever
/// command it's given — reimplementing pattern matching wasn't worth
/// the risk of a subtly different regex dialect. A zero-match search
/// records an explicit no-match observation (a bounded negative that
/// leaves no trace was the specific defect a prior run surfaced); a
/// match records one entry per file that actually matched, keyed by
/// that file's resolved path (fix 2), not by the search root or the
/// grep command line.
pub fn look_grep(workspace_dir: &Path, pattern: &str, root: &str) -> Result<LookOutcome, AuthoringError> {
    let root_path = Path::new(root);
    if !root_path.exists() {
        return Err(workspace::refuse(workspace_dir, "look", format!("no such path: {root}")));
    }
    // One session for the whole search: a recursive grep can match in
    // dozens of files, and each matched file resolves its own marker
    // (a search root can span a submodule or a nested worktree), but
    // files sharing a directory resolve once between them.
    let mut world = worldstate::Session::new();

    let mut args: Vec<&str> = Vec::new();
    if root_path.is_dir() {
        args.push("-r");
    }
    args.push("-I");
    args.push("-n");
    // `-H` unconditionally, because grep only prints the filename when it
    // was given more than one file to search. Without it a search of a
    // *single* file returns `<line>:<match>`, and the `split_once(':')`
    // below then read the line number as the filename: every such
    // observation was keyed on a bare integer, overlapped nothing, and —
    // since a bare integer has no parent directory — resolved its
    // world-tree marker from this process's working directory, which is
    // precisely the defect TET-5 removed everywhere else. Found by the
    // grounding pass over TET-5's own design memo, in that memo's own
    // extent.
    args.push("-H");
    args.push("-e");
    args.push(pattern);
    args.push(root);

    let output = Command::new("grep")
        .args(&args)
        .output()
        .map_err(|e| AuthoringError::Io(format!("could not run grep: {e}")))?;
    let stdout = String::from_utf8_lossy(&output.stdout).into_owned();

    let mut printed = String::new();
    let mut buf = pending::load(workspace_dir)?;

    if stdout.trim().is_empty() {
        // A bounded negative is about the tree it searched, so its marker
        // comes from the search root.
        let m = world.for_path(root_path);
        printed.push_str(&format!("no matches for '{pattern}' in {root}\n"));
        buf.push(PendingEntry {
            captured_at: workspace::now_unix(),
            kind: ObservationKind::NoMatch,
            key: search_key(root_path, &m.root),
            label: format!("no-match: {pattern} in {root}"),
            output: String::new(),
            world_root: m.root,
            world_state: m.state,
            pattern: pattern.to_string(),
        });
    } else {
        printed.push_str(&stdout);
        let mut by_file: std::collections::BTreeMap<String, Vec<String>> = std::collections::BTreeMap::new();
        for line in stdout.lines() {
            if let Some((file, rest)) = line.split_once(':') {
                by_file.entry(file.to_string()).or_default().push(rest.to_string());
            }
        }
        // One whole-search record beside the per-file hits. Without it a
        // search that matched says only which files it hit, and where it
        // was rooted — the thing a census turns on — is unrecoverable.
        // Its marker comes from the search root, exactly as the
        // zero-match record's always has.
        let m = world.for_path(root_path);
        let files = by_file.len();
        buf.push(PendingEntry {
            captured_at: workspace::now_unix(),
            kind: ObservationKind::Search,
            key: search_key(root_path, &m.root),
            label: format!(
                "search: {root} (grep: {pattern}) — {files} file{} matched",
                if files == 1 { "" } else { "s" }
            ),
            output: String::new(),
            world_root: m.root,
            world_state: m.state,
            pattern: pattern.to_string(),
        });
        for (file, matches) in by_file {
            let m = world.for_path(Path::new(&file));
            buf.push(PendingEntry {
                captured_at: workspace::now_unix(),
                kind: ObservationKind::GrepMatch,
                key: resolve_key(Path::new(&file)),
                label: format!("{file} (grep: {pattern})"),
                output: matches.join("\n"),
                world_root: m.root,
                world_state: m.state,
                pattern: pattern.to_string(),
            });
        }
    }
    pending::save(workspace_dir, &buf)?;
    Ok(LookOutcome { printed })
}

/// What `tetel look` was asked to do — open a path, or search one with
/// `--grep`. The single shape both the CLI and the MCP server build and
/// pass to [`dispatch`], so the two front ends can never drift on which
/// combination of missing flags gets refused, or with what text.
pub enum LookRequest {
    /// `tetel look <path> [--lines A:B]`.
    Open { path: Option<String>, lines: Option<(usize, usize)> },
    /// `tetel look --grep <pattern> <path-or-dir>`.
    Grep { pattern: String, root: Option<String> },
}

/// Dispatches a [`LookRequest`] to [`look_path`] or [`look_grep`],
/// refusing with the exact text the CLI has always printed when the
/// path-or-dir a mode needs was never given — lifted here (rather than
/// left as a bare `eprintln!` in `main.rs`) so the MCP server's
/// structured refusals carry the same guidance the CLI does, from the
/// one place that decides it.
pub fn dispatch(workspace_dir: &Path, req: LookRequest) -> Result<LookOutcome, AuthoringError> {
    match req {
        LookRequest::Grep { pattern, root } => {
            let root = root
                .ok_or_else(|| workspace::refuse(workspace_dir, "look", "`look --grep <pattern>` requires a path-or-dir"))?;
            look_grep(workspace_dir, &pattern, &root)
        }
        LookRequest::Open { path, lines } => {
            let path = path.ok_or_else(|| {
                workspace::refuse(
                    workspace_dir,
                    "look",
                    "usage: tetel look <path> [--lines A:B] | tetel look --grep <pattern> <path-or-dir>",
                )
            })?;
            look_path(workspace_dir, &path, lines)
        }
    }
}

pub struct RunOutcome {
    pub printed: String,
    pub exit_code: i32,
}

/// `tetel run <command...>` — executes `argv` directly (never through a
/// shell), prints its combined stdout/stderr, and records `argv`'s
/// command line plus the captured output into the pending buffer.
/// `run`'s own exit code mirrors the executed command's.
///
/// stdout and stderr are captured on separate pipes, each drained on
/// its own thread into one shared buffer, which reproduces `2>&1`'s
/// merged stream closely but not exactly: chunks from the two streams
/// can interleave in a different order than a real shell redirection
/// would produce, since nothing here observes their true fd-level
/// arrival order. Documented, not silently assumed exact.
pub fn run_command(workspace_dir: &Path, argv: &[String]) -> Result<RunOutcome, AuthoringError> {
    if argv.is_empty() {
        return Err(workspace::refuse(workspace_dir, "run", "no command given"));
    }
    // `run` is the one case where the process's own working directory is
    // the right answer rather than a fallback: a command names no path in
    // general, and it genuinely executed here.
    let world = worldstate::Session::new().for_cwd();
    let cmdline = argv.join(" ");

    let mut child = Command::new(&argv[0])
        .args(&argv[1..])
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(|e| AuthoringError::Io(format!("could not run `{cmdline}`: {e}")))?;

    let captured = Arc::new(Mutex::new(Vec::<u8>::new()));
    let stdout_pipe = child.stdout.take().expect("stdout was piped");
    let stderr_pipe = child.stderr.take().expect("stderr was piped");

    fn drain<R: Read + Send + 'static>(mut pipe: R, buf: Arc<Mutex<Vec<u8>>>) -> thread::JoinHandle<()> {
        thread::spawn(move || {
            let mut chunk = [0u8; 4096];
            loop {
                let n = pipe.read(&mut chunk).unwrap_or(0);
                if n == 0 {
                    break;
                }
                buf.lock().unwrap().extend_from_slice(&chunk[..n]);
            }
        })
    }
    let t_out = drain(stdout_pipe, Arc::clone(&captured));
    let t_err = drain(stderr_pipe, Arc::clone(&captured));

    let status = child.wait().map_err(|e| AuthoringError::Io(e.to_string()))?;
    t_out.join().ok();
    t_err.join().ok();

    let bytes = captured.lock().unwrap().clone();
    let output_text = String::from_utf8_lossy(&bytes).into_owned();
    let exit_code = status.code().unwrap_or(-1);

    let entry = PendingEntry {
        captured_at: workspace::now_unix(),
        kind: ObservationKind::Proc,
        key: cmdline.clone(),
        label: format!("proc: {cmdline} (exit {exit_code})"),
        output: output_text.clone(),
        world_root: world.root,
        world_state: world.state,
        pattern: String::new(),
    };
    let mut buf = pending::load(workspace_dir)?;
    buf.push(entry);
    pending::save(workspace_dir, &buf)?;

    Ok(RunOutcome { printed: output_text, exit_code })
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The reconciliation in [`search_key`] exists because two tools spell
    /// the search root: `fs::canonicalize` here and `git rev-parse
    /// --show-toplevel` in `worldstate`. On the machines this has been run
    /// on they agree, so an end-to-end test cannot reach this branch —
    /// removing the reconciliation entirely leaves the CLI tests green.
    /// A symlinked directory forces the disagreement deterministically.
    #[test]
    fn a_search_root_reached_through_a_symlink_is_keyed_the_way_its_marker_spells_it() {
        let base = std::env::temp_dir().join(format!("tetel-search-key-{}", std::process::id()));
        let _ = fs::remove_dir_all(&base);
        let real = base.join("real");
        fs::create_dir_all(&real).unwrap();
        let link = base.join("link");
        #[cfg(unix)]
        std::os::unix::fs::symlink(&real, &link).unwrap();

        // The divergence that matters runs this way round. `resolve_key`
        // canonicalizes, so the search side is always canonical; it is
        // *git* that can hand back a spelling with a symlink component,
        // because it answers from the path it was invoked through. So the
        // marker carries the link spelling and the search root is the real
        // directory — one directory, two names.
        //
        // Building `world_root` by canonicalizing instead would make the
        // two sides identical by construction and the assertion vacuous:
        // an earlier draft of this test did exactly that and passed with
        // the reconciliation deleted.
        let world_root = link.display().to_string();

        // Without reconciliation the census predicate — a byte comparison —
        // would refuse an honest worktree-rooted search over a difference
        // that means nothing.
        let key = search_key(&real, &world_root);
        assert_eq!(key, world_root, "same directory, so the marker's spelling wins");

        // A genuinely different directory keeps its own spelling, so the
        // predicate still fails — this is the case the census exists for.
        let sub = real.join("sub");
        fs::create_dir_all(&sub).unwrap();
        let sub_key = search_key(&sub, &world_root);
        assert_ne!(sub_key, world_root, "a subdirectory must not be reconciled into its parent");

        // An unresolvable marker is left alone rather than guessed about.
        assert_eq!(search_key(&real, ""), fs::canonicalize(&real).unwrap().display().to_string());

        let _ = fs::remove_dir_all(&base);
    }
}

//! ```
//!
//! The note names two branches and concludes there is one source, about a
//! file the fact never opened. A second fact overreached the same way,
//! the two contradicted each other, and a claim leaned on both by name.
//! Nothing in the tool noticed, because nothing compared a note against
//! its own extent.
//!
//! # What this is not
//!
//! It is a **scope** check, never a truth check. Whether the note is
//! *correct* about the location it names is exactly the limit this
//! project registered as permanently out of reach ("insincere
//! examination" — capture makes the extent honest, not the
//! interpretation). Nothing here touches that.
//!
//! It is also **human-owed, never a refusal**. A note may legitimately
//! name a location as context, contrast, or a pointer to what to read
//! next, and only a person can tell that from an unsupported inference.
//! Refusing would make the honest case unwritable to catch the dishonest
//! one.
//!
//! # What it catches, measured, and what it does not
//!
//! Of the two overreaching facts in the memo that motivated it, this
//! catches **one**. F6 named a file and a line range (`graph_utils.rs
//! ~560-566`) it never opened, which is the strong tell and fires here.
//! F7's note asserted the client "mirrors the server's" walk while its
//! extent covered only the client — an overreach that names no location
//! at all, and so is invisible to any check of this shape.
//!
//! One refinement was tried and rejected on the evidence: flagging a
//! `module::symbol` reference whose module never appears in the fact's
//! own captured output. Measured against the same three facts, it would
//! have flagged a legitimate quotation (F3 citing `object_utils::
//! load_parcel`, a call site inside the code it did read) while missing
//! both real overreaches, because `graph_utils` and `merge_utils` do
//! appear in the read source as call sites. Naming a symbol the code you
//! read calls is normal; concluding about what that symbol *does* is the
//! failure — and those two are not distinguishable by string matching.
//!
//! So: a file-and-line reference to unopened code is caught, and a
//! conclusion drawn without naming anything is not. That is a real
//! ceiling, not a to-do.
//!
//! # The `proc:` exemption, and why it stayed wide
//!
//! A fact whose extent is entirely `proc:` — minted from `run` rather
//! than `look` — is skipped. That exemption was suspected of being too
//! wide, because the way this check's own motivating failure recurred was
//! a fact minted against a **stale buffer**: two `look` calls failed on a
//! malformed line range, left the pending buffer untouched, and the next
//! mint folded a leftover command. The resulting note described source
//! the extent never covered, and landed squarely inside the exemption.
//!
//! The proposed narrowing was: exempt a `proc:` fact only when the paths
//! its note names appear in the command's own captured output — the file
//! a command actually touched will be there, one the author brought from
//! elsewhere will not.
//!
//! **Measured against a real store before building, and rejected on
//! precision.** As of 2026-08-07, on a store of 20 workspaces and 130
//! facts: 18 had `proc:`-only extents, naming 4 paths their own extent
//! does not already cover — 4 that a narrowing could ever report. Two are
//! exempt under the proposed rule. **The other 2 are the entire yield and
//! both are false positives** — one measurement fact whose note says
//! which files it added counters to, an edit the author made and saved as
//! diffs beside the memo. The advice this check prints there ("`look` at
//! it and mint a fact") is simply wrong.
//!
//! The count only means something against the check's own yield, which
//! the harness therefore prints beside it: **9 findings on `look`-minted
//! facts in the same corpus.** So the narrowing would take this check
//! from 9 findings to 11, adding no signal and two pieces of wrong
//! advice. That comparison is the argument. Re-run the harness rather
//! than trusting these numbers — the store grows, and they moved once
//! within a single day.
//!
//! Most `proc:`-only notes name a path their command already contains —
//! `awk`/`grep`/`sed` over a named file is how a grounding pass reads
//! code with line numbers. Those never reach the exemption at all:
//! the path is in the extent key, so `extent_covers` matches it. Assuming
//! otherwise inflated this measurement's first run to 7 false positives,
//! and both halves of the correction are pinned in `known_limits`.
//!
//! **What this does not establish.** The failure that prompted the
//! narrowing named no file at all — it discussed a request type and a
//! command-line flag — so it yields zero path tokens even under a
//! vocabulary accepting every filename-shaped token, and no path-keyed
//! rule could have caught *that instance*. But a stale-buffer note that
//! does happen to name a file is perfectly reachable, and a synthetic
//! replay confirms such a rule fires on it. The evidence here supports
//! "the only measured yield is noise", not "unreachable in principle" —
//! and an earlier draft of this doc claimed the latter.
//!
//! This is the same shape as the `module::symbol` refinement above: a
//! plausible tightening, measured, and killed by the measurement. The
//! harness that produced these numbers is kept in this module rather than
//! described, so the next person to suspect the exemption can re-run it
//! against their own store instead of re-deriving it. It grades facts **as
//! minted**, never as revised — see `measure::as_minted` for why that
//! distinction decides the answer.
//!
//! What the stale-buffer failure needed was not a narrower scope check.
//! It was for the mint to say what it had just folded, which is where the
//! fix landed.
//!
//! # Language-agnostic by construction
//!
//! Tetel documents systems in any language, so nothing here may be tuned
//! to one. There is no list of languages and no list of extensions.
//!
//! What counts as a filename is decided in two stages. Shape rules reject
//! what cannot be a file — prose abbreviations, version numbers, the
//! tails of method chains. Then the token's extension must be one this
//! workspace has **actually opened**, read out of the captured extents.
//! A `look` at a Swift file is what teaches the scanner that `.swift`
//! names a file here; nobody enumerates that in advance and no language
//! is excluded in advance.
//!
//! The second stage is load-bearing, not belt-and-braces. Attribute
//! access — `self.value`, `response.data` — is filename-shaped under any
//! shape rule worth having: a good stem, a good extension. Only "was
//! this extension ever opened" separates it from a real file, and it does
//! so without knowing which language is being discussed.
//!
//! Its cost is that the vocabulary is per-extension, not per-language: a
//! workspace that has opened `mix.exs` has not thereby learned `.ex`. The
//! alternative is a hard-coded map from extension to language, which is
//! exactly the coupling this avoids. Pinned by a test rather than left to
//! be rediscovered.

use crate::facts::Fact;

/// A location a note names that its own extent does not cover.
pub struct OutsideExtent {
    pub fact_id: String,
    /// The location token as it appears in the note, verbatim — so a
    /// reader can find it by searching rather than by guessing what was
    /// normalised.
    pub mentioned: String,

        Err(e) if e.kind() == io::ErrorKind::NotFound => Ok(Counters::default()),
        Err(e) => Err(e),
    }
}

fn save_counters(workspace_dir: &Path, c: &Counters) -> io::Result<()> {
    ensure(workspace_dir)?;
    let json = serde_json::to_string_pretty(c).map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;
    fs::write(counters_path(workspace_dir), json)
}

pub enum Kind {
    Fact,
    Claim,
    Prose,
    Target,
}

/// Allocates and persists the next id for `kind`, returning e.g. `F3`.
/// See the module doc comment: this id is workspace-relative and gives
/// no promise of uniqueness or stability outside `workspace_dir`.
pub fn next_id(workspace_dir: &Path, kind: Kind) -> io::Result<String> {
    let mut c = load_counters(workspace_dir)?;
    let (n, prefix) = match kind {
        Kind::Fact => {
            c.fact += 1;
            (c.fact, "F")
        }
        Kind::Claim => {
            c.claim += 1;
            (c.claim, "C")
        }
        Kind::Prose => {
            c.prose += 1;
            (c.prose, "P")
        }
        Kind::Target => {
            c.target += 1;
            (c.target, "T")
        }
    };
    save_counters(workspace_dir, &c)?;
    Ok(format!("{prefix}{n}"))
}

/// Append one JSON value as its own line to a `.jsonl` log — the
/// append-only ledger for facts/claims/prose, mirroring
/// `evidence::record`'s one-line, never-rewritten append.
pub fn append_jsonl<T: Serialize>(path: &Path, value: &T) -> io::Result<()> {
    ensure(path.parent().unwrap_or_else(|| Path::new(".")))?;
    let line = serde_json::to_string(value).map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;
    let mut f = OpenOptions::new().create(true).append(true).open(path)?;
    writeln!(f, "{line}")
}

/// Read every line of a `.jsonl` log. A missing file means nothing has

//! `tetel claim` — assert, revise, or withdraw a proposition resting on
//! facts. Refuses without `--cites` (a claim must cite at least one
//! fact) and refuses on an unknown fact id. Before accepting a new
//! claim, prints an overlap report: existing facts, not among those
//! cited, that share an overlap key (see `pending.rs`'s doc comment on
//! fix 2) with the ones being cited — this is how the tool surfaces
//! evidence the author may have forgotten they already had.
//!
//! `--revise`/`--withdraw` are append-only, mirroring `tclaim`: both
//! refuse without `--why`, and a revision keeps the old proposition in
//! the log rather than overwriting it.

use std::collections::BTreeSet;
use std::io;
use std::path::{Path, PathBuf};

use serde::{Deserialize, Serialize};

use crate::facts;
use crate::workspace::{self, AuthoringError, Kind};

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "event")]
pub enum ClaimEvent {
    Create {
        id: String,
        prop: String,
        from: Vec<String>,
        timestamp: u64,
    },
    Revise {
        id: String,
        #[serde(default)]
        prop: Option<String>,
        #[serde(default)]
        from: Option<Vec<String>>,
        why: String,
        timestamp: u64,
    },
    Withdraw {
        id: String,
        why: String,
        timestamp: u64,
    },
}

pub struct Claim {
    pub id: String,
    pub prop: String,
    pub from: Vec<String>,
    pub withdrawn: bool,
    pub revisions: usize,
}

fn log_path(workspace_dir: &Path) -> PathBuf {
    workspace_dir.join("claims.jsonl")
}

pub fn load_all(workspace_dir: &Path) -> io::Result<Vec<Claim>> {
    let events: Vec<ClaimEvent> = workspace::read_jsonl(&log_path(workspace_dir))?;
    let mut by_id: std::collections::BTreeMap<String, Claim> = std::collections::BTreeMap::new();
    let mut order: Vec<String> = Vec::new();
    for ev in events {
        match ev {
            ClaimEvent::Create { id, prop, from, .. } => {
                order.push(id.clone());
                by_id.insert(id.clone(), Claim { id, prop, from, withdrawn: false, revisions: 0 });
            }
            ClaimEvent::Revise { id, prop, from, .. } => {
                if let Some(c) = by_id.get_mut(&id) {
                    if let Some(p) = prop {
                        c.prop = p;
                    }
                    if let Some(f) = from {
                        c.from = f;
                    }
                    c.revisions += 1;
                }
            }
            ClaimEvent::Withdraw { id, .. } => {
                if let Some(c) = by_id.get_mut(&id) {
                    c.withdrawn = true;
                }
            }
        }
    }
    Ok(order.into_iter().filter_map(|id| by_id.remove(&id)).collect())
}

pub fn exists(workspace_dir: &Path, id: &str) -> io::Result<bool> {
    Ok(load_all(workspace_dir)?.iter().any(|c| c.id == id))
}

fn parse_ids(csv: &str) -> Vec<String> {
    csv.split(',').map(str::trim).filter(|s| !s.is_empty()).map(String::from).collect()
}

pub struct CreateOutcome {
    pub claim: Claim,
    /// `(fact id, current note)` for every non-cited fact sharing a
    /// designator with the cited ones.
    pub overlap: Vec<(String, String)>,
}

/// `tetel claim --proposition <text> --cites F1,F3`.
pub fn create(workspace_dir: &Path, prop: &str, from_csv: &str) -> Result<CreateOutcome, AuthoringError> {
    let ids = parse_ids(from_csv);
    if ids.is_empty() {
        return Err(workspace::refuse(
            workspace_dir,
            "claim",
            "a claim must rest on at least one fact (--cites was missing or empty); try `tetel query facts` to find one, or mint a new fact with `tetel look`/`tetel run` + `tetel fact`",
        ));
    }
    let mut missing = Vec::new();
    for id in &ids {
        if !facts::exists(workspace_dir, id)? {
            missing.push(id.clone());
        }
    }
    if !missing.is_empty() {
        return Err(workspace::refuse(
            workspace_dir,
            "claim",
            format!("cited fact(s) do not exist: {}; try `tetel query facts` to see what exists", missing.join(", ")),
        ));
    }
    if prop.trim().is_empty() {
        return Err(workspace::refuse(workspace_dir, "claim", "no --proposition given; a claim needs a proposition"));
    }

    let overlap = overlap_report(workspace_dir, &ids)?;

    let id = workspace::next_id(workspace_dir, Kind::Claim)?;
    let event = ClaimEvent::Create { id: id.clone(), prop: prop.to_string(), from: ids.clone(), timestamp: workspace::now_unix() };
    workspace::append_jsonl(&log_path(workspace_dir), &event)?;

    Ok(CreateOutcome { claim: Claim { id, prop: prop.to_string(), from: ids, withdrawn: false, revisions: 0 }, overlap })
}

//! `tetel render` — assemble the workspace's current prose state into
//! markdown on stdout, followed by an evidence ledger built from the
//! workspace's claims. Mirrors `trender`, plus fix 1 from this port's own
//! design memo: the prototype's `trender` had nothing downstream that
//! read its output back, so a rendered document and `tetel check` never
//! connected — every check reported "no evidence ledger found" against
//! a document this same tool had just produced. Appending a ledger
//! table in the shape `ledger::import` already reads closes that loop
//! without inventing a third evidence shape.
//!
//! Headings render at their own declared depth (`#` * level), not a
//! single fixed depth — see `prose.rs`'s doc comment on why that's a
//! fix, not a stylistic choice. A revised block renders only its
//! current text; superseded text lives in `prose.jsonl`'s history but
//! never here.
//!
//! The ledger is strictly an addition after the prose: nothing here can
//! change a single byte the prose loop already wrote, so the document a
//! human reads stays exactly what was authored — only `tetel check`
//! sees the appended table as evidence to grade.

use std::io;
use std::path::Path;

use crate::claims;
use crate::prose;

pub fn render(workspace_dir: &Path) -> io::Result<String> {
    let blocks = prose::load_all(workspace_dir)?;
    let mut out = String::new();
    for (i, b) in blocks.iter().enumerate() {
        if i > 0 {
            out.push('\n');
        }
        if b.heading {
            let level = b.level.unwrap_or(2).clamp(1, 6);
            out.push_str(&"#".repeat(level as usize));
            out.push(' ');
            out.push_str(&b.text);
            out.push('\n');
        } else {
            out.push_str(&b.text);
            out.push('\n');
            if !b.cite.is_empty() {
                out.push('\n');
                out.push_str(&format!("*cites: {}*\n", b.cite.join(", ")));
            }
        }
    }
    let claim_list = claims::load_all(workspace_dir)?;
    out.push_str(&render_targets(&crate::targets::load_all(workspace_dir)?, &claim_list));
    out.push_str(&render_ledger(&claim_list));
    out.push_str(&render_facts(
        &crate::facts::load_all(workspace_dir)?,
        &claim_list,
    ));
    Ok(out)
}

/// Appends the modification-target section — the symbols this design
/// tells an implementer to modify, each with the fact that censuses it.
///
/// # Why it renders when it is empty
///
/// Because the hole is the finding. A declared target is refused without
/// a census at declaration time, so a *declared* target is always
/// censused; what no refusal can reach is a target the author never
/// declared, since deciding that a memo recommended something it never
/// declared is the heuristic read of prose the whole design rejects.
///
/// Visibility is the answer instead. Once a document has any claim at
/// all, this section renders — as "none declared" when it is empty — so
/// a memo full of tell-the-implementer language with an empty section
/// shows its own gap to every reader. An absent section would make the
/// same omission invisible, which is the failure mode, not the fix.
///
/// Withdrawn targets are dropped rather than struck through: a target is
/// withdrawn precisely when it stopped being a target, and the log keeps
/// the history for anyone auditing the workspace.
fn render_targets(targets: &[crate::targets::Target], claims: &[claims::Claim]) -> String {
    let live: Vec<&crate::targets::Target> = targets.iter().filter(|t| !t.withdrawn).collect();
    // Nothing to be silent about yet: a document with no claims is not a
    // document making recommendations.
    if live.is_empty() && claims.is_empty() {
        return String::new();
    }
    let mut out = String::from("\n## Modification targets\n\n");
    if live.is_empty() {
        out.push_str(
            "None declared. A target is a symbol this design tells an implementer to modify; \
             declaring one requires a search of the whole worktree for it. Nothing forces a \
             recommendation to be declared, so an empty section is not evidence that none exist.\n",
        );
        return out;
    }
    out.push_str("| target | censused by |\n|---|---|\n");
    for t in live {
        out.push_str(&format!("| `{}` | {} |\n", t.symbol, t.from));
    }
    out
}

/// Appends a facts table after the evidence ledger.
///
/// # Why the document has to carry this
///
/// Before it did, `prose --cites` accepted fact ids as readily as claim
/// ids and `render` wrote them into the document, but no fact appeared
/// anywhere in the output — so `tetel check` reported `cited but
/// undefined: [F5]` on the first real memo, correctly, and would have on
/// every memo that ever cited a fact from prose.
///
/// The deeper reason is what a reader loses without it. A fact's captured
/// extent is the one field in this system no author can type, and reading
/// notes against extents is where review value has actually shown up —
/// the FORK-94 review's sharpest finding was a note concluding about a
/// file its extent never covered. Without this table that comparison is
/// possible only by opening the workspace, which a reviewer of a
/// committed document does not have.
///
/// # What is deliberately not here
///
/// The `key` is an absolute machine-local path; the `label` is
/// repo-relative. Only the label is rendered — a committed document
/// should not carry `/Users/<someone>/...`, and the label is what a
/// reader can act on anyway.
///
/// Captured output is not rendered either. It is unbounded (a `run` can
/// capture megabytes), it is in the snapshot for anyone who needs it, and
/// a document that inlined it would bury the prose it exists to support.
    /// two facts asserting opposite things about the same code disagree
    /// about the world or about the same world, which before this the
    /// ledger could not answer at all. Same snapshot dependency as
    /// `mint_windows`.
    pub tree_states: Vec<crate::worldstate::RootStates>,
    /// Facts whose markers predate roots being recorded, so their tree
    /// state describes the process's working directory rather than what
    /// they read. Reported rather than passed over: an ungradable record
    /// is not a matching one.
    pub tree_ungradable: Vec<String>,
    /// Declared modification targets whose cited fact does not census
    /// them, re-verified against the shipped snapshot — a **machine
    /// failure**.
    ///
    /// `tetel target` refuses these at declaration, so a workspace-
    /// authored memo cannot produce one. What this catches is the
    /// document that never passed through that verb: hand-authored,
    /// edited after rendering, or carrying a target row its own snapshot
    /// does not have. Both directions are checked, because tampering can
    /// go either way — a row invented in the document, or a target whose
    /// citation stopped censusing it.
    ///
    /// It is an objective contradiction between a document and the record
    /// it claims to rest on, which is what the machine partition is for.
    pub uncensused_targets: Vec<String>,
    /// Target rows in a document that shipped no snapshot, so nothing
    /// can verify them — **human-owed**, never a failure.
    ///
    /// Same standing choice as every other snapshot-dependent finding: a
    /// missing snapshot grades the tooling's history rather than the
    /// document, and every memo authored before `render --out` existed
    /// lacks one.
    pub unverifiable_targets: Vec<String>,
    /// True when the memo's ledger has no scope columns for any claim to
    /// declare into — a tetel-authored ledger. Reported once at document
    /// level rather than once per claim; see
    /// [`claims_without_declared_scope`] for why that changed.
    pub ledger_has_no_scope_columns: bool,
    /// One line per grounded claim describing how its evidence stands:
    /// witnessed (extent captured by this tool, in a named workspace) or
    /// ingested (extent typed by a caller). Human-owed, printed item by
    /// item, never a failure — see [`grounding_provenance`].
    pub grounding_provenance: Vec<String>,
    /// `(claim id, pass, note)` per record whose verdict is
    /// [`Verdict::Qualifies`]. Human-owed, never a failure.
    ///
    /// Until this existed, a qualifying verdict was invisible. On the
    /// first real independent grounding pass, the two claims the grounder
    /// declined to confirm — because the numbers they rest on could not
    /// be verified from what it was given — printed as plainly "grounded",
    /// while the one claim where it qualified a single premise of a
    /// multi-premise argument was the only thing reddening the report.
    /// The check fired on the wrong claim and was silent on the right
    /// ones.
    pub qualified_claims: Vec<(String, String, String)>,
    /// Claims **out of proof**: every record on file grades a wording this
    /// claim no longer carries, and nothing has graded the current one.
    /// The proof-house sense exactly — the stamp no longer certifies this
    /// barrel. A machine failure; see [`analyze_ledger`].
    ///
    /// The remedy is to **reprove**: ground the claim again against what it
    /// now says. Nothing else clears it, and nothing clears it silently —
    /// the ledger is append-only, so the superseding record is added rather
    /// than the stale one edited.
    pub out_of_proof: Vec<String>,
    /// Records that graded an earlier wording of a claim which *has* since
    /// been reproved. Human-owed history, never a failure — the claim is
    /// back in proof, and these are the marks from before it was. See
    /// [`analyze_ledger`] on why the distinction matters.
    pub superseded_evidence: Vec<String>,
}

